    public static class DynamicData
    {
        public const string ResourcePath = "SovietBlueHour/dynamic_entities.v1";
        public static bool Loaded { get; private set; }
        public static string Error { get; private set; }
        public static DynRoot Root { get; private set; }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetSession()
        {
            Loaded = false;
            Error = null;
            Root = null;
        }

        public static bool EnsureLoaded()
        {
            if (Loaded) return true;
            try
            {
                var asset = Resources.Load<TextAsset>(ResourcePath);
                if (asset == null)
                {
                    Error = "缺少 Resources/" + ResourcePath + ".json";
                    return false;
                }
                var root = JsonUtility.FromJson<DynRoot>(asset.text);
                if (root == null || root.vehicles == null || root.vehicles.Length != 48 ||
                    root.tram == null || root.flame == null || root.roads == null)
                {
                    Error = "dynamic_entities.v1 解析失败或数量不符（期望 48 车辆 + 电车 + 圣火）";
                    return false;
                }
                Root = root;
                Loaded = true;
                Error = null;
                return true;
            }
            catch (System.Exception e)
            {
                Error = "dynamic_entities.v1 加载异常：" + e.Message;
                return false;
            }
        }

        public static DynVehicle FindVehicle(string entityId)
        {
            if (!EnsureLoaded() || string.IsNullOrEmpty(entityId)) return null;
            foreach (var v in Root.vehicles)
                if (v != null && v.entity_id == entityId) return v;
            return null;
        }

        public static DynRoad FindRoad(string id)
        {
            if (!EnsureLoaded()) return null;
            foreach (var r in Root.roads)
                if (r != null && r.id == id) return r;
            return null;
        }

        public static DynBoarding[] Boarding(DynVehicle v)
        {
            return v != null && v.boarding_candidates != null ? v.boarding_candidates : new DynBoarding[0];
        }
    }
